on conflict (id) do update set
  title = excluded.title,
  author = excluded.author,
  published_year = excluded.published_year,
  isbn = excluded.isbn,
  pillar = excluded.pillar,
  subcategory = excluded.subcategory,
  note = excluded.note,
  cover_color = excluded.cover_color;

update public.books
set cover_color = '#c69a62'
where id = 'dune';

update public.books
set note = 'A sweeping challenge to familiar stories about the origins of inequality and society.'
where id = 'dawn-of-everything';